/**
 * For WaSOS files, check if any exceed the target system's upload limit.
 * Oversized files are marked with skipped: true, reason: 'oversized'.
 * They remain in payload.files so POST to Rayvn log can report them.
 * Output 1- pass files smaller than 1mb
 * Output 2 - mark files larger than 1mb
 */
const MAX_UPLOAD_BYTES = 1048576; // 1 MB

const files = msg.payload.files || [];
let has_oversized = false;

msg.payload.files = files.map(file => {
    if (file.size && file.size > MAX_UPLOAD_BYTES) {
        has_oversized = true;
        return { ...file, skipped: true, reason: "oversized" };
    }
    return file;
});

if (has_oversized) {
    return [null, msg];
} else {
    return [msg, null];
}

/**
 * For Rayvn files: check if the user already shared a link manually.
 * If a URL is in the text, clear files silently — no notification needed.
 *
 * Output 1: No URL → genuinely non-transferable (only attatchment)
 * Output 2: URL found → user shared link, clean up silently
 */
const url_pattern = /(?:https?:\/\/|ftp:\/\/|www\.)\S+/i;
const has_url = msg.payload.text && url_pattern.test(msg.payload.text);

if (has_url) {
    msg.payload.files = [];
    return [null, msg];
} else {
    return [msg, null];
}

/**
 * CIM file handling not yet implemented.
 * Mark all files as skipped.
 */
node.warn("CIM attachment classification not implemented — treating as non-transferable");

msg.payload.files = (msg.payload.files || []).map(file => ({
    ...file,
    skipped: true,
    reason: "cim_not_implemented"
}));

return msg;

/**
 * All files are transferable and within size limits.
 * Entry proceeds with no modifications.
 */
return msg;

/**
 * Oversized files are already marked with skipped: true, reason: 'oversized'.
 * No text notice or notification here — POST to Rayvn log collects all
 * skipped/failed files and builds one combined notification.
 */
return msg;

/**
 * Rayvn files cannot be downloaded programmatically.
 * Mark all files with skipped: true, reason: 'non_transferable'.
 * No text notice or notification here — POST to Rayvn log handles that.
 */
msg.payload.files = (msg.payload.files || []).map(file => ({
    ...file,
    skipped: true,
    reason: "non_transferable"
}));

return msg;
